// Writes public/_redirects: static rules plus pattern rules that 301 the legacy nested URLs
// (/electrical-services/x/, /locations/state/, /locations/state/city/, /locations/state/city/service/)
// to the flat URLs. Run with: npx tsx --tsconfig tsconfig.json scripts/gen-redirects.tsx
import { writeFileSync } from "node:fs";
import { cityPages } from "@/lib/sitemap";

const states = new Map<string, string>();
for (const p of cityPages()) states.set(p.state.slug, p.state.code.toLowerCase());

const lines = [
  "# Generated by scripts/gen-redirects.tsx. Cloudflare Pages redirects; www -> apex is a zone rule.",
  "# Online requests were retired; old form URLs go to the contact page.",
  "/request-service/ /contact/ 301",
  "/thank-you/ /contact/ 301",
  "# Retired 2026-10-20: too close to the Portland, OR page.",
  "/home-rewiring-in-portland-me/ /electricians-in-portland-me/ 301",
  "# Legacy nested URLs (most specific first).",
];
for (const [slug, code] of states) lines.push(`/locations/${slug}/:city/:service/ /:service-in-:city-${code}/ 301`);
for (const [slug, code] of states) lines.push(`/locations/${slug}/:city/ /electricians-in-:city-${code}/ 301`);
lines.push("/locations/:state/ /electricians-in-:state/ 301");
lines.push("/electrical-services/:slug/ /:slug/ 301");

writeFileSync("public/_redirects", lines.join("\n") + "\n");
const dynamic = lines.filter((l) => l.includes(":")).length;
console.log(`_redirects: ${lines.filter((l) => !l.startsWith("#")).length} rules, ${dynamic} dynamic, states ${states.size}`);
